@prefix hubs: <https://example.org/agent-hub#> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

# S1-003 contract, version 3 (engine-validated, constraints preserved from v1)
#
# Basis: shapes.ttl (frozen v1 baseline). Preserved verbatim:
#   - KnowledgeAssertionShape with sh:targetClass, sh:or for promoted/superseded
#   - GroundedAssertionShape (untargeted, documentation) with full v1 constraints
#   - EvidenceShape, DelegationGrantShape with all v1 property constraints
#
# Additions over v1 (all strengthening, no weakening):
#   - sh:message on status sh:in -> "stale_or_unknown_status" (maps to oracle)
#   - sh:message on EvidenceShape.independenceGroup -> "evidence_missing_independence_group"
#   - Split locatedIn into minCount (missing_effective_scope) and maxCount
#     (multiple_effective_scopes) so messages match oracle exactly
#   - New SPARQL on KnowledgeAssertionShape (guarded by status="promoted"):
#     * missing_promotion_activity (deduplicates v1 sh:or, cleaner message)
#     * insufficient_distinct_canonical_sources (NEW check not in v1 SHACL)
#     * insufficient_independence_groups (NEW check not in v1 SHACL)
#   - New SPARQL on KnowledgeAssertionShape (guarded by status="superseded"):
#     * missing_superseding_assertion (deduplicates v1 sh:or, cleaner message)
#   - New SPARQL scope checks:
#     * evidence_scope_mismatch
#     * promotion_actor_scope_mismatch
#     * subject_scope_mismatch (DelegationGrantShape)
#     * actor_scope_mismatch (DelegationGrantShape)
#   - sh:message "negative_budget" on DelegationGrantShape.budget
#
# Forbidden tokens absent: sh:maxExclusiveInclusive, sh:closed true,
#   accepted, withdrawn.

hubs:KnowledgeAssertionShape a sh:NodeShape ;
  sh:targetClass hubs:KnowledgeAssertion ;
  sh:property [
    sh:path hubs:supportedBy ;
    sh:minCount 0 ;
    sh:class hubs:Evidence ; sh:severity sh:Violation ] ;
  sh:property [
    sh:path hubs:status ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:string ;
    sh:in ( "proposed" "under_review" "promoted" "challenged"
            "retracted" "superseded" "rejected" ) ;
    sh:message "stale_or_unknown_status" ] ;
  sh:property [
    sh:path hubs:locatedIn ; sh:minCount 1 ;
    sh:class hubs:Workspace ; sh:message "missing_effective_scope" ] ;
  sh:property [
    sh:path hubs:locatedIn ; sh:maxCount 1 ;
    sh:message "multiple_effective_scopes" ] ;
  sh:or (
    [ sh:not [ sh:property [ sh:path hubs:status ; sh:hasValue "promoted" ] ] ]
    [ sh:property [
        sh:path prov:wasGeneratedBy ; sh:minCount 1 ; sh:maxCount 1 ;
        sh:class hubs:PromotionActivity ; sh:severity sh:Violation ;
        sh:message "missing_promotion_activity" ] ;
      sh:property [
        sh:path hubs:supportedBy ; sh:minCount 2 ;
        sh:node hubs:EvidenceShape ; sh:severity sh:Violation ;
        sh:message "insufficient_evidence_count" ] ]
  ) ;
  sh:or (
    [ sh:not [ sh:property [ sh:path hubs:status ; sh:hasValue "superseded" ] ] ]
    [ sh:property [
        sh:path hubs:supersededBy ; sh:minCount 1 ; sh:maxCount 1 ;
        sh:class hubs:KnowledgeAssertion ; sh:severity sh:Violation ;
        sh:message "missing_superseding_assertion" ] ]
  ) ;
  # Additional SPARQL constraints (strengthening over v1):
  # These duplicate the sh:or checks but produce clean sh:message values
  # that the comparison framework can classify.
  sh:sparql [
    sh:message "missing_promotion_activity" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT $this WHERE {
  $this hubs:status "promoted" .
  FILTER NOT EXISTS {
    $this prov:wasGeneratedBy ?activity .
    ?activity a hubs:PromotionActivity .
  }
}
""" ] ;
  sh:sparql [
    sh:message "missing_superseding_assertion" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:status "superseded" .
  FILTER NOT EXISTS {
    $this hubs:supersededBy ?succ .
    ?succ a hubs:KnowledgeAssertion .
  }
}
""" ] ;
  sh:sparql [
    sh:message "insufficient_distinct_canonical_sources" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:status "promoted" .
  ?this hubs:supportedBy ?evidence .
  ?evidence hubs:canonicalSourceId ?canonical .
}
GROUP BY $this
HAVING (COUNT(DISTINCT ?canonical) < 2)
""" ] ;
  sh:sparql [
    sh:message "insufficient_independence_groups" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:status "promoted" .
  ?this hubs:supportedBy ?evidence .
  ?evidence hubs:independenceGroup ?group .
}
GROUP BY $this
HAVING (COUNT(DISTINCT ?group) < 2)
""" ] ;
  sh:sparql [
    sh:message "evidence_scope_mismatch" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:locatedIn ?scope .
  $this hubs:supportedBy ?ev .
  ?ev hubs:locatedIn ?evScope .
  FILTER(?evScope != ?scope)
}
""" ] ;
  sh:sparql [
    sh:message "promotion_actor_scope_mismatch" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT $this WHERE {
  $this hubs:locatedIn ?scope .
  $this prov:wasGeneratedBy ?act .
  ?act hubs:actorScope ?actScope .
  FILTER(?actScope != ?scope)
}
""" ] .

hubs:GroundedAssertionShape a sh:NodeShape ;
  sh:property [
    sh:path hubs:status ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:hasValue "promoted" ; sh:message "not_promoted_status" ] ;
  sh:property [
    sh:path prov:wasGeneratedBy ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:class hubs:PromotionActivity ; sh:message "missing_promotion_activity" ] ;
  sh:property [
    sh:path hubs:supportedBy ; sh:minCount 2 ;
    sh:node hubs:EvidenceShape ; sh:message "insufficient_evidence_count" ] ;
  sh:sparql [
    sh:message "insufficient_distinct_canonical_sources" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:supportedBy ?evidence .
  ?evidence hubs:canonicalSourceId ?canonical .
}
GROUP BY $this
HAVING (COUNT(DISTINCT ?canonical) < 2)
""" ] ;
  sh:sparql [
    sh:message "insufficient_independence_groups" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:supportedBy ?evidence .
  ?evidence hubs:independenceGroup ?group .
}
GROUP BY $this
HAVING (COUNT(DISTINCT ?group) < 2)
""" ] .

hubs:EvidenceShape a sh:NodeShape ;
  sh:targetClass hubs:Evidence ;
  sh:property [
    sh:path hubs:canonicalSourceId ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:string ] ;
  sh:property [
    sh:path hubs:publisherId ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:string ] ;
  sh:property [
    sh:path hubs:independenceGroup ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:string ;
    sh:message "evidence_missing_independence_group" ] ;
  sh:property [
    sh:path hubs:resolverVersion ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:string ] ;
  sh:property [
    sh:path hubs:metadataFrozenAt ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:dateTime ] .

hubs:DelegationGrantShape a sh:NodeShape ;
  sh:targetClass hubs:DelegationGrant ;
  sh:property [
    sh:path hubs:subject ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:or ( [ sh:class hubs:HumanUser ]
            [ sh:class hubs:SharedWorkspace ]
            [ sh:class hubs:PlatformOpsSubject ] ) ] ;
  sh:property [
    sh:path hubs:actor ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:class hubs:AgentInstallation ] ;
  sh:property [ sh:path hubs:locatedIn ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:class hubs:Workspace ; sh:message "missing_effective_scope" ] ;
  sh:property [ sh:path hubs:locatedIn ; sh:maxCount 1 ;
    sh:message "multiple_effective_scopes" ] ;
  sh:property [ sh:path hubs:actions ; sh:minCount 1 ] ;
  sh:property [ sh:path hubs:resources ; sh:minCount 1 ] ;
  sh:property [ sh:path hubs:constraints ; sh:maxCount 1 ] ;
  sh:property [ sh:path hubs:jti ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:string ] ;
  sh:property [ sh:path hubs:ttl ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:dayTimeDuration ;
    sh:maxInclusive "PT15M"^^xsd:dayTimeDuration ] ;
  sh:property [ sh:path hubs:budget ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:decimal ; sh:minInclusive 0 ;
    sh:message "negative_budget" ] ;
  sh:property [
    sh:path hubs:status ; sh:minCount 1 ; sh:maxCount 1 ;
    sh:datatype xsd:string ;
    sh:in ( "proposed" "active" "revoked" "expired" "exhausted" "denied" ) ] ;
  sh:sparql [
    sh:message "subject_scope_mismatch" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:locatedIn ?scope .
  $this hubs:subject ?subj .
  ?subj hubs:locatedIn ?subScope .
  FILTER(?subScope != ?scope)
}
""" ] ;
  sh:sparql [
    sh:message "actor_scope_mismatch" ;
    sh:select """
PREFIX hubs: <https://example.org/agent-hub#>
SELECT $this WHERE {
  $this hubs:locatedIn ?scope .
  $this hubs:actor ?act .
  ?act hubs:locatedIn ?actScope .
  FILTER(?actScope != $scope)
}
""" ] .

{
  "schema": "agentos.s1-003-fixtures/v1",
  "expected_lifecycle_states": {
    "KnowledgeAssertion": [
      "proposed",
      "under_review",
      "promoted",
      "challenged",
      "retracted",
      "superseded",
      "rejected"
    ],
    "DelegationGrant": [
      "proposed",
      "active",
      "revoked",
      "expired",
      "exhausted",
      "denied"
    ]
  },
  "evidence_catalog": {
    "evidence-a": {
      "type": "Evidence",
      "canonical_source_id": "source-a",
      "publisher_id": "publisher-a",
      "independence_group": "group-a",
      "resolver_version": "resolver-v1",
      "metadata_frozen_at": "2026-08-24T00:00:00Z",
      "located_in": "workspace-a"
    },
    "evidence-b": {
      "type": "Evidence",
      "canonical_source_id": "source-b",
      "publisher_id": "publisher-b",
      "independence_group": "group-b",
      "resolver_version": "resolver-v1",
      "metadata_frozen_at": "2026-08-24T00:00:00Z",
      "located_in": "workspace-a"
    },
    "mirror-a-1": {
      "type": "Evidence",
      "canonical_source_id": "source-a",
      "publisher_id": "publisher-a",
      "independence_group": "group-a",
      "resolver_version": "resolver-v1",
      "metadata_frozen_at": "2026-08-24T00:00:00Z",
      "located_in": "workspace-a",
      "url": "https://mirror-one.invalid/a"
    },
    "mirror-a-2": {
      "type": "Evidence",
      "canonical_source_id": "source-a",
      "publisher_id": "publisher-a-mirror",
      "independence_group": "group-a",
      "resolver_version": "resolver-v1",
      "metadata_frozen_at": "2026-08-24T00:00:00Z",
      "located_in": "workspace-a",
      "url": "https://mirror-two.invalid/a"
    },
    "evidence-no-group": {
      "type": "Evidence",
      "canonical_source_id": "source-c",
      "publisher_id": "publisher-c",
      "resolver_version": "resolver-v1",
      "metadata_frozen_at": "2026-08-24T00:00:00Z",
      "located_in": "workspace-a"
    },
    "evidence-cross-scope": {
      "type": "Evidence",
      "canonical_source_id": "source-d",
      "publisher_id": "publisher-d",
      "independence_group": "group-d",
      "resolver_version": "resolver-v1",
      "metadata_frozen_at": "2026-08-24T00:00:00Z",
      "located_in": "workspace-b"
    }
  },
  "fixtures": [
    {
      "id": "assertion-proposed-inherited",
      "tags": ["valid", "lifecycle", "inheritance", "probe-proposed"],
      "profile": "open",
      "expected": {"conforms": true},
      "additional_expectations": {
        "promoted_only": {"conforms": false, "primary_reason": "not_promoted_status"}
      },
      "data": {
        "type": "KnowledgeAssertion",
        "status": "proposed",
        "located_in": "workspace-a",
        "inherited_content_object_properties": {"digest": "sha256:fixture", "media_type": "text/plain"}
      }
    },
    {
      "id": "assertion-under-review",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "KnowledgeAssertion", "status": "under_review", "located_in": "workspace-a"}
    },
    {
      "id": "assertion-promoted-grounded",
      "tags": ["valid", "lifecycle", "grounded"],
      "profile": "open",
      "expected": {"conforms": true},
      "additional_expectations": {"promoted_only": {"conforms": true}},
      "data": {
        "type": "KnowledgeAssertion",
        "status": "promoted",
        "located_in": "workspace-a",
        "supported_by": ["evidence-a", "evidence-b"],
        "generated_by": {"type": "PromotionActivity", "actor_scope": "workspace-a"}
      }
    },
    {
      "id": "assertion-challenged",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "KnowledgeAssertion", "status": "challenged", "located_in": "workspace-a"}
    },
    {
      "id": "assertion-retracted",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "KnowledgeAssertion", "status": "retracted", "located_in": "workspace-a"}
    },
    {
      "id": "assertion-superseded",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {
        "type": "KnowledgeAssertion",
        "status": "superseded",
        "located_in": "workspace-a",
        "superseded_by": {"type": "KnowledgeAssertion", "id": "assertion-new"}
      }
    },
    {
      "id": "assertion-rejected",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "KnowledgeAssertion", "status": "rejected", "located_in": "workspace-a"}
    },
    {
      "id": "grant-proposed",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "DelegationGrant", "status": "proposed", "located_in": "workspace-a", "subject": {"type": "HumanUser", "workspace": "workspace-a"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["read"], "resources": ["artifact-a"], "jti": "jti-proposed", "ttl": "PT10M", "budget": 1}
    },
    {
      "id": "grant-active",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "DelegationGrant", "status": "active", "located_in": "workspace-a", "subject": {"type": "SharedWorkspace", "workspace": "workspace-a"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["read"], "resources": ["artifact-a"], "jti": "jti-active", "ttl": "PT15M", "budget": 3}
    },
    {
      "id": "grant-revoked",
      "tags": ["valid", "lifecycle", "revoked"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "DelegationGrant", "status": "revoked", "located_in": "workspace-a", "subject": {"type": "PlatformOpsSubject", "workspace": "workspace-a"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["operate"], "resources": ["control-plane"], "jti": "jti-revoked", "ttl": "PT5M", "budget": 0}
    },
    {
      "id": "grant-expired",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "DelegationGrant", "status": "expired", "located_in": "workspace-a", "subject": {"type": "HumanUser", "workspace": "workspace-a"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["read"], "resources": ["artifact-a"], "jti": "jti-expired", "ttl": "PT1M", "budget": 0}
    },
    {
      "id": "grant-exhausted",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "DelegationGrant", "status": "exhausted", "located_in": "workspace-a", "subject": {"type": "HumanUser", "workspace": "workspace-a"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["read"], "resources": ["artifact-a"], "jti": "jti-exhausted", "ttl": "PT5M", "budget": 0}
    },
    {
      "id": "grant-denied",
      "tags": ["valid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": true},
      "data": {"type": "DelegationGrant", "status": "denied", "located_in": "workspace-a", "subject": {"type": "HumanUser", "workspace": "workspace-a"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["write"], "resources": ["artifact-a"], "jti": "jti-denied", "ttl": "PT5M", "budget": 0}
    },
    {
      "id": "invalid-orphan-promoted",
      "tags": ["invalid", "near-miss", "probe-promotion"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "missing_promotion_activity"},
      "data": {"type": "KnowledgeAssertion", "status": "promoted", "located_in": "workspace-a", "supported_by": ["evidence-a", "evidence-b"]}
    },
    {
      "id": "invalid-mirror-sybil-promoted",
      "tags": ["invalid", "near-miss", "probe-mirror"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "insufficient_distinct_canonical_sources"},
      "data": {"type": "KnowledgeAssertion", "status": "promoted", "located_in": "workspace-a", "supported_by": ["mirror-a-1", "mirror-a-2"], "generated_by": {"type": "PromotionActivity", "actor_scope": "workspace-a"}}
    },
    {
      "id": "invalid-no-independence-group",
      "tags": ["invalid", "near-miss", "probe-independence"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "evidence_missing_independence_group"},
      "data": {"type": "KnowledgeAssertion", "status": "promoted", "located_in": "workspace-a", "supported_by": ["evidence-a", "evidence-no-group"], "generated_by": {"type": "PromotionActivity", "actor_scope": "workspace-a"}}
    },
    {
      "id": "invalid-cross-scope-evidence",
      "tags": ["invalid", "ownership_scope"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "evidence_scope_mismatch"},
      "data": {"type": "KnowledgeAssertion", "status": "promoted", "located_in": "workspace-a", "supported_by": ["evidence-a", "evidence-cross-scope"], "generated_by": {"type": "PromotionActivity", "actor_scope": "workspace-a"}}
    },
    {
      "id": "invalid-promotion-actor-scope",
      "tags": ["invalid", "ownership_scope"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "promotion_actor_scope_mismatch"},
      "data": {"type": "KnowledgeAssertion", "status": "promoted", "located_in": "workspace-a", "supported_by": ["evidence-a", "evidence-b"], "generated_by": {"type": "PromotionActivity", "actor_scope": "workspace-b"}}
    },
    {
      "id": "invalid-orphan-scope",
      "tags": ["invalid", "ownership_scope"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "missing_effective_scope"},
      "data": {"type": "KnowledgeAssertion", "status": "proposed"}
    },
    {
      "id": "invalid-multiple-scope",
      "tags": ["invalid", "ownership_scope", "near-miss"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "multiple_effective_scopes"},
      "data": {"type": "KnowledgeAssertion", "status": "proposed", "located_in": ["workspace-a", "workspace-b"]}
    },
    {
      "id": "invalid-stale-status-accepted",
      "tags": ["invalid", "stale-vocabulary"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "stale_or_unknown_status"},
      "data": {"type": "KnowledgeAssertion", "status": "accepted", "located_in": "workspace-a"}
    },
    {
      "id": "invalid-superseded-without-successor",
      "tags": ["invalid", "lifecycle"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "missing_superseding_assertion"},
      "data": {"type": "KnowledgeAssertion", "status": "superseded", "located_in": "workspace-a"}
    },
    {
      "id": "invalid-grant-subject-scope",
      "tags": ["invalid", "ownership_scope"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "subject_scope_mismatch"},
      "data": {"type": "DelegationGrant", "status": "active", "located_in": "workspace-a", "subject": {"type": "HumanUser", "workspace": "workspace-b"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["read"], "resources": ["artifact-a"], "jti": "jti-cross-subject", "ttl": "PT5M", "budget": 1}
    },
    {
      "id": "invalid-grant-negative-budget",
      "tags": ["invalid", "constraint"],
      "profile": "open",
      "expected": {"conforms": false, "primary_reason": "negative_budget"},
      "data": {"type": "DelegationGrant", "status": "active", "located_in": "workspace-a", "subject": {"type": "HumanUser", "workspace": "workspace-a"}, "actor": {"type": "AgentInstallation", "workspace": "workspace-a"}, "actions": ["read"], "resources": ["artifact-a"], "jti": "jti-negative", "ttl": "PT5M", "budget": -1}
    }
  ]
